var workflow = new WorkflowBuilder(researchAgent)
    .AddEdge(researchAgent, writerAgent)
    .AddEdge(writerAgent, reviewerAgent)
    .Build();

AIAgent pipeline = workflow.AsAIAgent(
    id: "content-pipeline",
    name: "Content Pipeline Agent",
    description: "Researches, writes and reviews content");

AgentSession s = await pipeline.CreateSessionAsync();
await foreach (var u in pipeline.RunStreamingAsync(messages, s)) Console.Write(u.Text);
